import Foundation
import CoreFoundation

/// Validate a parsed configuration against the structural keywords generated by our bundled schema, then
/// the native model's shortcut/helper semantics. Never resolve a user-controlled `$schema` URL or fetch remote data.
func validateConfigTable(_ table: [String: ConfigValue]) -> Result<DecodedConfig, ConfigError> {
    var table = table
    // Earlier releases wrote these unassigned slots into every new file. Ignore only those placeholders,
    // so removing vertical bindings does not invalidate unrelated preferences on upgrade. Preserve disk bytes.
    if case .table(var mouse)? = table["mouse"], let retiredWheel = mouse["verticalWheel"] {
        guard case .table(let slots) = retiredWheel,
              slots.allSatisfy({ ["up", "down"].contains($0.key) && $0.value == .table([:]) }) else {
            return .failure(ConfigError(reason: "mouse.verticalWheel: no longer supported; remove this table and use mouse.horizontalWheel.left/right"))
        }
        mouse.removeValue(forKey: "verticalWheel")
        table["mouse"] = .table(mouse)
    }
    let value = ConfigValue.table(table).jsonObject
    // The schema is application source, generated into the signed resource by the same Core module.
    let schema = try! JSONSerialization.jsonObject(with: Data(configSchemaJSON.utf8)) as! [String: Any]
    if let reason = schemaViolation(schema, value, path: "") { return .failure(ConfigError(reason: reason)) }
    // The parser yields only finite numbers (it rejects inf and nan); fail closed regardless.
    guard let data = try? JSONSerialization.data(withJSONObject: value) else { return .failure(ConfigError(reason: "invalid TOML: the values cannot be checked")) }
    return decodeConfig(data)
}

private func schemaViolation(_ schema: [String: Any], _ value: Any, path: String) -> String? {
    let label = path.isEmpty ? "config" : path
    let number = value as? NSNumber
    let boolean = number.map { CFGetTypeID($0) == CFBooleanGetTypeID() } ?? false
    let type = schema["type"] as? String
    let matches: Bool
    switch type {
    case "object": matches = value is [String: Any]
    case "array": matches = value is [Any]
    case "string": matches = value is String
    case "boolean": matches = boolean
    case "number": matches = number != nil && !boolean
    default: matches = true // Untyped oneOf branches constrain required keys/properties below.
    }
    if !matches { return "\(label): expected \(type!)" }
    if let values = schema["enum"] as? [String], let string = value as? String, !values.contains(string) {
        return "\(label): unsupported value"
    }
    if let branches = schema["oneOf"] as? [[String: Any]],
       branches.filter({ schemaViolation($0, value, path: path) == nil }).count != 1 {
        return "\(label): use an empty object or set exactly one of shell, shortcut or helper"
    }
    if let string = value as? String {
        if let minimum = schema["minLength"] as? Int, string.unicodeScalars.count < minimum {
            return "\(label): cannot be empty"
        }
        if let pattern = schema["pattern"] as? String, string.range(of: pattern, options: .regularExpression) == nil {
            return "\(label): value does not match the configuration schema"
        }
    }
    if let number, !boolean {
        if let minimum = schema["minimum"] as? Double, number.doubleValue < minimum { return "\(label): minimum is \(minimum)" }
        if let maximum = schema["maximum"] as? Double, number.doubleValue > maximum { return "\(label): maximum is \(maximum)" }
    }
    if let array = value as? [Any] {
        if let minimum = schema["minItems"] as? Int, array.count < minimum { return "\(label): needs at least \(minimum) item(s)" }
        if let item = schema["items"] as? [String: Any] {
            for (index, element) in array.enumerated() {
                if let reason = schemaViolation(item, element, path: "\(path)[\(index)]") { return reason }
            }
        }
    }
    if let object = value as? [String: Any] {
        if let maximum = schema["maxProperties"] as? Int, object.count > maximum { return "\(label): too many properties" }
        for key in schema["required"] as? [String] ?? [] where object[key] == nil { return "\(label).\(key): required" }
        let properties = schema["properties"] as? [String: [String: Any]] ?? [:]
        for key in object.keys.sorted() {
            let childPath = path.isEmpty ? key : "\(path).\(key)"
            if let names = schema["propertyNames"] as? [String: Any],
               let reason = schemaViolation(names, key, path: childPath) { return reason }
            if let rule = properties[key] ?? (schema["additionalProperties"] as? [String: Any]) {
                if let reason = schemaViolation(rule, object[key]!, path: childPath) { return reason }
            } else if schema["additionalProperties"] as? Bool == false { return "\(childPath): unknown setting" }
        }
    }
    return nil
}
